presets.css:
/* Puff · QQ通栏无缝版（强制顶底栏完全填满） */

@import url('https://fonts.googleapis.com/css2?family=ZCOOL+KuaiLe&display=swap');

.chat-thread {

  --dress-chat-bg-overlay: transparent !important; 

  --dress-header-radius: 0px !important;

  --dress-header-border: none !important;

  --dress-header-shadow: none !important;

  --dress-header-title-color: #C9184A;

  --dress-header-title-weight: 700;

  --dress-header-icon-color: #FFB6C1;

  --dress-compose-bar-radius: 0px !important;

  --dress-compose-bar-border: none !important;

  --dress-compose-bar-shadow: none !important;

  --dress-compose-bar-fg: #C9184A;

  --dress-timestamp-color: #C9184A;

}

.chat-thread, .chat-bubble, .chat-compose-input, .chat-thread-center h2 {

  font-family: 'ZCOOL KuaiLe', 'MiSans', sans-serif !important;

}

/* ========== 【关键修复】强制顶部完全填满 ========== */

.chat-thread-top {

  padding: 0 !important;

  margin: 0 !important;

  left: 0 !important;

  top: 0 !important;

  width: 100% !important;

  box-sizing: border-box !important;

}

.chat-thread-pill {

  width: 100% !important;

  margin: 0 !important;

  border-radius: 0 !important;

  border-left: none !important;

  border-right: none !important;

  /* 增加安全区适配，确保贴合顶部 */

  padding-top: env(safe-area-inset-top, 0px) !important; 

  background: rgba(255, 255, 255, 0.7) url('https://cdn.phototourl.com/free/2026-09-09-708b332c-89dd-44b0-be56-88b9364114f0.jpg') center/cover !important;

  border-bottom: 4px solid #FFFFFF !important;

  box-shadow: 0 4px 0 #FFB6C1 !important;

}

/* ========== 【关键修复】强制底部完全填满 ========== */

.chat-compose {

  padding: 0 !important;

  margin: 0 !important;

  left: 0 !important;

  bottom: 0 !important;

  width: 100% !important;

  box-sizing: border-box !important;

  background: transparent !important;

}

.chat-compose-bar {

  width: 100% !important;

  margin: 0 !important;

  border-radius: 0 !important;

  border-left: none !important;

  border-right: none !important;

  /* 底部增加安全区，让手势条区域也铺满粉色背景 */

  padding-bottom: calc(env(safe-area-inset-bottom, 0px) + 10px) !important; 

  background: rgba(255, 255, 255, 0.8) url('https://cdn.phototourl.com/free/2026-09-09-10f04403-3f38-4f29-a816-7316c9b353b3.jpg') center/cover !important;

  border-top: 4px solid #FFFFFF !important;

  box-shadow: 0 -4px 0 #FFB6C1 !important;

}

/* 底栏外部如果有包裹层，也给扒了 */

.chat-compose > * {

  width: 100% !important;

  border-radius: 0 !important;

}

/* ========== 头像（保持纯净） ========== */

.chat-ava, .chat-ava-sm {

  border-radius: 50% !important;

  border: 2px solid #FFFFFF !important;

  box-shadow: 0 0 0 4px #FFB6C1, 0 4px 8px rgba(255,182,193,0.6) !important;

  background: transparent !important;

  padding: 0 !important;

  position: static !important; 

}

.chat-ava::before, .chat-ava::after, .chat-ava-sm::before, .chat-ava-sm::after {

  content: none !important; display: none !important;

}

/* ========== 气泡（保持果冻质感） ========== */

.chat-bubble {

  font-size: 14px !important;

  line-height: 1.4 !important;

  padding: 8px 14px !important;

  border: none !important;

  position: relative !important;

  background: 

    linear-gradient(rgba(255, 240, 243, 0.75), rgba(255, 240, 243, 0.75)),

    url('https://cdn.phototourl.com/free/2026-09-09-ea7efd01-0926-4ee5-ad1d-7dc5dd073ea6.jpg') center/cover !important;

  color: #C9184A !important;

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff, -1px 1px 0 #fff, 1px 1px 0 #fff;

  box-shadow: inset 2px 2px 5px rgba(255,255,255,0.9), inset -2px -2px 5px rgba(255,182,193,0.6), 0 3px 6px rgba(255,182,193,0.4) !important;

}

.chat-msg.is-me .chat-bubble {

  background: linear-gradient(rgba(255, 215, 225, 0.75), rgba(255, 180, 195, 0.75)), url('https://cdn.phototourl.com/free/2026-09-09-ea7efd01-0926-4ee5-ad1d-7dc5dd073ea6.jpg') center/cover !important;

  color: #A80022 !important;

  border-radius: 14px 14px 2px 14px !important;

  text-shadow: none !important; 

}

.chat-msg.is-them .chat-bubble {

  background: linear-gradient(rgba(255, 255, 255, 0.8), rgba(255, 230, 235, 0.8)), url('https://cdn.phototourl.com/free/2026-09-09-ea7efd01-0926-4ee5-ad1d-7dc5dd073ea6.jpg') center/cover !important;

  color: #C9184A !important;

  border-radius: 14px 14px 14px 2px !important;

}

.chat-bubble::before, .chat-bubble::after {

  content: none !important; display: none !important;

}

/* 昵称、时间戳 */

.chat-msg-name {

  background: rgba(255, 182, 193, 0.6) !important;

  color: #A80022 !important;

  border-radius: 999px !important;

  padding: 2px 8px !important;

  font-size: 10px !important;

  text-shadow: none !important;

}

.chat-msg-timestamp {

  background: rgba(255, 255, 255, 0.7) !important;

  color: #C9184A !important;

  padding: 2px 6px !important;

  border-radius: 999px !important;

  text-shadow: none !important;

}

/* 语音条、图片、卡片优化 */

.puff-voice-pill {

  border-radius: 999px !important;

  background: linear-gradient(145deg, #FFFFFF, #FFF0F3) !important;

  border: 2px solid #FFFFFF !important;

  box-shadow: 0 0 0 3px #FFB6C1, 0 4px 8px rgba(255,182,193,0.3) !important;

  color: #C9184A !important;

}

.puff-voice-waves, .puff-voice-wave {

  background-color: #FFB6C1 !important;

  border-radius: 999px !important;

  width: 3px !important;

}

.puff-voice-glyph, .puff-voice-dur {

  color: #C9184A !important;

  font-size: 12px !important;

}

.puff-photo, .chat-bubble-sticker {

  border-radius: 12px !important;

  border: 2px solid #FFFFFF !important;

  box-shadow: 0 0 0 2px #FFB6C1, 0 8px 16px rgba(255, 182, 193, 0.4) !important;

}

.chat-msg.has-transfer .chat-msg-body,

.chat-msg.has-red-envelope .chat-msg-body,

.chat-msg.has-gift .chat-msg-body,

.puff-transfer, .puff-gift {

  border-radius: 12px !important;

  border: 2px solid #FFFFFF !important;

  background: linear-gradient(145deg, #FFF9FA, #FFDCE4) !important;

  box-shadow: 0 0 0 2px #FFB6C1, 0 8px 16px rgba(255,182,193,0.3) !important;

  color: #C9184A !important;

  overflow: hidden !important;

}

/* 底部输入栏内部 */

.chat-compose-plus {

  background: url('https://cdn.phototourl.com/free/2026-09-09-142ed9f3-1b19-4fa0-b139-1cf69546a24d.png') center/contain no-repeat !important;

  color: transparent !important;

  font-size: 0 !important;

  text-indent: -9999px;

  overflow: hidden;

}

.chat-compose-icon, .chat-compose-icon.is-voice, .chat-compose-icon.is-more, .chat-compose-icon.is-reply {

  color: #FFB6C1 !important;

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff, -1px 1px 0 #fff, 1px 1px 0 #fff;

}

.chat-compose-icon.is-send.ready, .chat-compose-icon.is-send, .chat-compose-send, .send-btn, .icon-send {

  background-image: url('https://cdn.phototourl.com/free/2026-09-09-12cfc6ed-2614-4ea7-b8a3-926a18820fac.jpg') !important;

  background-size: contain !important;

  background-repeat: no-repeat !important;

  background-position: center !important;

  color: transparent !important;

  font-size: 0 !important;

  text-indent: -9999px;

  width: 28px !important;

  height: 28px !important;

  transition: transform 0.2s ease;

}

.chat-compose-icon.is-send:active { transform: scale(0.85); }

/* 通知 */

.chat-thread-notice {

  background: rgba(255, 255, 255, 0.9) !important;

  border-radius: 999px !important;

  color: #C9184A !important;

  border: 2px solid #FFB6C1;

}

/* 顶部加一层从上往下变淡的透光渐变 */

.chat-thread-pill {

    background: linear-gradient(to bottom, rgba(255,255,255,0.5), rgba(255,255,255,0.1)), url('https://cdn.phototourl.com/free/2026-09-09-708b332c-89dd-44b0-be56-88b9364114f0.jpg') center/cover !important;

}

/* 底部加一层从下往上变淡的透光渐变 */

.chat-compose-bar {

    background: linear-gradient(to top, rgba(255,255,255,0.5), rgba(255,255,255,0.1)), url('https://cdn.phototourl.com/free/2026-09-09-10f04403-3f38-4f29-a816-7316c9b353b3.jpg') center/cover !important;

}

.chat-compose-plus, .chat-compose-icon, .chat-compose-icon.is-voice {

    background: rgba(255, 255, 255, 0.6);

    border-radius: 12px;

    padding: 6px;

    margin: 0 4px;

    box-shadow: inset 2px 2px 4px #fff, inset -2px -2px 4px #FFB6C1, 2px 2px 4px rgba(255,182,193,0.4);

}

.chat-bubble {

    box-shadow: 

        inset 2px 2px 5px rgba(255,255,255,0.9), 

        inset -2px -2px 5px rgba(255,182,193,0.6), 

        0 4px 8px rgba(255,182,193,0.35), 

        0 0 0 2px rgba(255,255,255,0.4) !important;

}

/* 昵称变成饱满的小胶囊 */

.chat-msg-name {

    background: linear-gradient(145deg, #FFFFFF, #FFE3E8) !important;

    border: 1px solid #FFB6C1 !important;

    box-shadow: 0 2px 4px rgba(255, 182, 193, 0.4) !important;

    font-weight: bold !important;

}

/* 时间戳也是，但更小一点 */

.chat-msg-timestamp {

    background: linear-gradient(145deg, rgba(255, 255, 255, 0.9), rgba(255, 182, 193, 0.7)) !important;

    border: 1px solid #FFFFFF !important;

    box-shadow: 0 2px 4px rgba(255, 182, 193, 0.3) !important;

}

.chat-thread-scroll::-webkit-scrollbar {

    width: 3px; /* 极细 */

}

.chat-thread-scroll::-webkit-scrollbar-track {

    background: transparent; /* 透明轨道 */

}

.chat-thread-scroll::-webkit-scrollbar-thumb {

    background: rgba(255, 182, 193, 0.4); /* 半透明粉 */

    border-radius: 99px;

}

.chat-thread-scroll::-webkit-scrollbar-thumb:hover {

    background: rgba(255, 182, 193, 0.8);

}

/* 顶部标题果冻胶囊 */

.chat-thread-center h2 {

  background: rgba(255, 255, 255, 0.6) !important;

  padding: 4px 14px !important;

  border-radius: 999px !important;

  border: 1px solid #FFFFFF !important;

  box-shadow: 0 2px 4px rgba(255, 182, 193, 0.4) !important;

}

/* 顶栏图标果冻底座 */

.chat-back, .chat-thread-head-more, .chat-thread-head-xinsheng {

  background: rgba(255, 255, 255, 0.65) !important;

  border-radius: 50% !important;

  width: 30px !important;

  height: 30px !important;

  display: flex !important;

  justify-content: center !important;

  align-items: center !important;

  margin: 0 4px !important;

  border: 1px solid #FFFFFF !important;

  box-shadow: 0 2px 4px rgba(255, 182, 193, 0.4), inset 2px 2px 4px #FFFFFF !important;

}

/* ========== 高级细节美化（无布局风险，纯内层优化） ========== */

/* G. 引用消息：高级果冻便签 */

.chat-qq-quote {

  background: linear-gradient(145deg, rgba(255,255,255,0.7), rgba(255,230,235,0.7)) !important;

  border: 1px solid #FFB6C1 !important;

  border-left: 4px solid #FF4D6D !important;

  border-radius: 8px !important;

  box-shadow: 0 2px 6px rgba(255,182,193,0.3), inset 1px 1px 2px #FFFFFF !important;

  color: #A80022 !important;

}

/* F. 系统居中通知：珍珠悬浮胶囊 */

.chat-thread-notice {

  background: rgba(255, 255, 255, 0.85) !important;

  border: 1px solid #FFFFFF !important;

  box-shadow: 0 0 0 1px #FFB6C1, 0 4px 12px rgba(255,182,193,0.3) !important;

  color: #C9184A !important;

  backdrop-filter: blur(4px) !important; /* 轻微模糊更透亮 */

}

/* H. 语音消息：高定果冻壳，去掉难看红块 */

.puff-voice-pill {

  background: linear-gradient(145deg, rgba(255,255,255,0.9), rgba(255,215,225,0.9)) !important;

  border: 1px solid #FFFFFF !important;

  box-shadow: 0 0 0 2px #FFB6C1, 0 4px 10px rgba(255,182,193,0.4), inset 2px 2px 4px #FFFFFF !important;

}

/* 改成高级的细长粉白渐进波浪 */

.puff-voice-waves, .puff-voice-wave {

  background: linear-gradient(to bottom, #FFB6C1, #FF4D6D) !important;

  border-radius: 999px !important;

  width: 2px !important;

}

.puff-voice-glyph, .puff-voice-dur {

  color: #C9184A !important;

  text-shadow: -1px -1px 0 #fff, 1px -1px 0 #fff !important;

}

/* I. 图片/贴纸：超薄相框 */

.puff-photo, .chat-bubble-sticker {

  border: 3px solid #FFFFFF !important;

  box-shadow: 0 0 0 1px #FFB6C1, 0 6px 14px rgba(255,182,193,0.35) !important;

  border-radius: 12px !important;

}

/* J. 长按气泡触发的"点赞/反应"功能：高级粉白小果冻 */

.chat-reaction-chip {

  background: linear-gradient(145deg, #FFFFFF, #FFE3E8) !important;

  border: 1px solid #FFB6C1 !important;

  box-shadow: 0 2px 6px rgba(255,182,193,0.5) !important;

}

.chat-reaction-chip-emoji {

  filter: drop-shadow(0 1px 1px rgba(0,0,0,0.15));

}

.chat-reaction-chip-meta {

  color: #C9184A !important;

  font-size: 10px !important;

}

/* K. 红包/转账卡：轻奢果冻卡（去掉黑边黑字） */

.puff-transfer, .puff-gift {

  background: linear-gradient(145deg, #FFF9FA, #FFDCE4) !important;

  border: 1px solid #FFFFFF !important;

  box-shadow: 0 0 0 1px #FFB6C1, 0 8px 16px rgba(255,182,193,0.3), inset 2px 2px 4px #FFFFFF !important;

  color: #C9184A !important;

  overflow: hidden !important;

}

/* M. 长按气泡弹出的操作板（复制/转发/删除） */

.chat-bubble-actions-card {

  background: rgba(255, 245, 248, 0.98) !important;

  border: 1px solid #FFB6C1 !important;

  border-radius: 10px !important;

  box-shadow: 0 8px 20px rgba(255,182,193,0.5) !important;

}

.chat-bubble-actions-item {

  color: #C9184A !important;

  border-bottom: 1px solid rgba(255,182,193,0.3) !important;

}

.chat-bubble-actions-item:active {

  background: #FFE3E8 !important;

}

.chat-bubble-actions-item:last-child { border-bottom: none !important; }

/* L. 输入框高级细节：光标变成粉红色，占位符变半透明红 */

.chat-compose-input {

  caret-color: #FF4D6D !important; /* 输入光标是俏皮的樱桃粉 */

}

.chat-compose-input::placeholder {

  color: rgba(201, 24, 74, 0.5) !important;

  text-shadow: -1px -1px 0 #fff, 1px 1px 0 #fff !important;

}

/* 输入框聚焦时果冻隆起 */

.chat-compose-bar:focus-within {

  border: 2px solid #FFB6C1 !important;

  box-shadow: 0 0 0 2px #FF4D6D, 0 6px 14px rgba(255,182,193,0.6), inset 2px 2px 4px #FFFFFF !important;

  transform: translateY(-1px) !important; /* 微微上浮 */

}

/* 消息进入时从右/左滑入 */

.chat-msg.is-me {

  animation: msg-in-right 0.3s ease-out;

}

.chat-msg.is-them {

  animation: msg-in-left 0.3s ease-out;

}

@keyframes msg-in-right {

  from { transform: translateX(20px); opacity: 0; }

  to { transform: translateX(0); opacity: 1; }

}

@keyframes msg-in-left {

  from { transform: translateX(-20px); opacity: 0; }

  to { transform: translateX(0); opacity: 1; }

}
